import java.util.concurrent.ConcurrentHashMap

/**
 * Full-colour brand marks of 网络测试, bundled as vector path data: nothing is downloaded at runtime.
 * Each service is drawn as an app-icon style tile: [NetBrandArt] gives the tile background and the
 * inset, [vector] the mark in its real colours (multi-colour where the logo is).
 *
 * Sources (paths re-serialised to absolute commands; colours as published by each source):
 *  - Simple Icons 16.34.0, CC0 1.0, https://simpleicons.org — googlegemini, reddit, appletv, bilibili,
 *    alibabadotcom, apple, qq, wikipedia, baidu.
 *  - svgl, https://github.com/pheralb/svgl (MIT; logos collected from each brand's own assets) —
 *    openai, claude, grok, discord, tiktok, x, telegram, disneyplus, hulu, netflix, spotify, twitch,
 *    youtube, cloudflare, github, paypal, steam.
 *  - LobeHub Icons, https://github.com/lobehub/lobe-icons (MIT) — doubao.
 *  - Google's sign-in branding guidelines — the four-colour "G".
 * The Gemini sparkle uses the Simple Icons path filled with Gemini's published blue-violet gradient.
 * NetEase has no permissively licensed vector mark, so its tile sets the 网易 wordmark in type.
 * The marks remain the trademarks of their owners and are only used to label each service.
 */
internal class NetBrandArt(
    /** Tile background, top to bottom (equal for a flat tile). */
    val top: Long,
    val bottom: Long,
    /** Inset of the mark on each side, as a fraction of the tile size. */
    val inset: Float,
)

internal object NetBrandIcons {
    private val built = ConcurrentHashMap<String, ImageVector>()

    /** Full-colour mark for [slug], drawn untinted; null when the service has no bundled mark. */
    fun vector(slug: String): ImageVector? {
        val mark = marks[slug] ?: return null
        return built.getOrPut(slug) { mark.build(slug) }
    }

    /** Tile background and inset for [slug]; null when the service has no bundled mark. */
    fun art(slug: String): NetBrandArt? = marks[slug]?.art

    /** Primary brand colour per mark, ARGB (used where a single colour stands for the service). */
    val colors: Map<String, Long> = mapOf(
        "openai" to 0xFF10A37FL,
        "claude" to 0xFFD97757L,
        "doubao" to 0xFF1E37FCL,
        "googlegemini" to 0xFF8E75B2L,
        "grok" to 0xFF000000L,
        "discord" to 0xFF5865F2L,
        "tiktok" to 0xFF000000L,
        "reddit" to 0xFFFF4500L,
        "x" to 0xFF000000L,
        "telegram" to 0xFF26A5E4L,
        "appletv" to 0xFF000000L,
        "bilibili" to 0xFF00A1D6L,
        "disneyplus" to 0xFF113CCFL,
        "hulu" to 0xFF1CE783L,
        "netflix" to 0xFFE50914L,
        "spotify" to 0xFF1ED760L,
        "twitch" to 0xFF9146FFL,
        "youtube" to 0xFFFF0000L,
        "alibabadotcom" to 0xFFFF6A00L,
        "apple" to 0xFF000000L,
        "cloudflare" to 0xFFF38020L,
        "github" to 0xFF181717L,
        "paypal" to 0xFF002991L,
        "steam" to 0xFF000000L,
        "qq" to 0xFF1EBAFCL,
        "wikipedia" to 0xFF000000L,
        "google" to 0xFF4285F4L,
        "baidu" to 0xFF2932E1L,
    )

    private class Stop(val offset: Float, val argb: Long)
    private class Layer(val d: String, val argb: Long = 0xFF000000L, val from: Offset? = null, val to: Offset? = null, val stops: List<Stop> = emptyList())
    private class Mark(val art: NetBrandArt, val x: Float, val y: Float, val w: Float, val h: Float, val evenOdd: Boolean, val layers: List<Layer>) {
        fun build(slug: String): ImageVector {
            val longest = maxOf(w, h)
            val builder = ImageVector.Builder(
                name = "brand-$slug", defaultWidth = (24f * w / longest).dp, defaultHeight = (24f * h / longest).dp,
                viewportWidth = w, viewportHeight = h,
            )
            builder.addGroup(translationX = -x, translationY = -y)
            for (layer in layers) {
                val fill = if (layer.from != null && layer.to != null) {
                    Brush.linearGradient(*layer.stops.map { it.offset to Color(it.argb) }.toTypedArray(), start = layer.from, end = layer.to)
                } else SolidColor(Color(layer.argb))
                builder.addPath(
                    pathData = addPathNodes(layer.d), fill = fill,
                    pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                )
            }
            builder.clearGroup()
            return builder.build()
        }
    }

